const input = $input.first().json;
const projectId = String(input.query?.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(input.query?.path || '').replace(/\.\./g, '').replace(/^\//,'');

if (!projectId || !subPath) {
  return [{ json: [] }];
}

const basePath = '/home/node/n8n-files/projects';
const targetDir = `${basePath}/${projectId}/${subPath}`;

return [{ json: { targetDir, projectId, subPath } }];

const input = $input.first().json;
const stdout = input.stdout || '';

if (!stdout.trim()) {
  return [{ json: [] }];
}

const files = stdout.trim().split('\n')
  .filter(line => line.trim())
  .map(line => {
    const parts = line.split('|');
    if (parts.length >= 3) {
      return {
        name: parts[2],
        size: parseInt(parts[0]) || 0,
        modified: parts[1]
      };
    }
    return null;
  })
  .filter(f => f && f.name && !f.name.startsWith('.'));

return [{ json: files }];
